CREATE TABLE `oee_tool_bt_0421` (
  `tool_id` varchar(12) NOT NULL COMMENT 'length extend to 12 for sintering "before/after" omi -- 2020/03/18 lkchena',
  `tool_name` varchar(16) DEFAULT NULL,
  `status` varchar(6) DEFAULT NULL COMMENT '1. if tool is hold/down/pm ... then can''t process lot <-- it is key! we are MES, not "過帳" system\n2. SPC also can "auto hold" tool, when spc ooc/oos\n3. Our Messenger should show alarm or something\n2017/06/25 lkchena\n\nWAIT UP TEST PM OFF MON LOST HOLD DOWN   2017/11/09 lkchena\n',
  `ws_type` varchar(12) NOT NULL DEFAULT '0' COMMENT 'change to use string, compatible with aruroal 2020/03/29 lkchena\n2020/03/17 lkchena\n',
  `ws_func` varchar(24) DEFAULT NULL,
  `tool_type` varchar(12) NOT NULL DEFAULT '0',
  `tool_grp_id` varchar(24) DEFAULT NULL,
  `tool_func` varchar(24) DEFAULT NULL,
  `ui_type` int(11) DEFAULT 0 COMMENT '2020/04/16 lkchena\r\nom_base form type:\r\n0: default: normal tool\r\n200: sintering - front-end\r\n201: sintering - back-end\r\n\r\n>1000 and < 2000 --> need prepare job\r\n1000: forming \r\n\r\n>= 2000 --> reserve\r\n\r\nothers: wait add ',
  `tool_grp` varchar(32) DEFAULT NULL COMMENT 'tool_group for mold dispatch, \nex: 成型機: 100T成形,150T成形,20T成形,250T成形...\n2019/12/07 lkchena\n',
  `status1` int(11) NOT NULL DEFAULT 0 COMMENT 'status1:\n0: no any status(can''t run) -- 2020/03/10 lkchena\n1: ongoing  <-- wait drop -- 2020/02/28 lkchena\n2: change mold\n3: complete prepare job(change mold), wait run, lost   //sintering directly change to 3 w/o 2\n-- not use -- 4: test\n5: lost: complete test, ready to run <-- no lot track-in\n6: tool process, track-in with lot\n9: complete( 91: shift record, 99: shift complete )\n-1: delete by user  2018/10/22 lkchena\n\nstatus1=2 for change mold_id( before mfg run the order )\neng only can set 2, when no order(mfg/rd) is running --  2020/01/30 lkchena\n\n//for tool_order_bth -- 2020/02/15 lkchena\nstatus1:\n91: shift record -- 2019/01/02 lkchena\n99: shift complete order\n\nstatus is mysql keyword, so rename to status1 -- 2020/01/02 lkchena',
  `mold_id` varchar(16) DEFAULT NULL COMMENT 'just like mask ... \n2019/12/21 lkchena',
  `recipe_id` varchar(32) DEFAULT NULL,
  `er` varchar(32) DEFAULT NULL,
  `mfg_no` varchar(16) DEFAULT NULL,
  `part_id` varchar(24) DEFAULT NULL,
  `part_raw` varchar(24) DEFAULT NULL,
  `route_id` varchar(24) DEFAULT NULL,
  `rd_flag` int(11) DEFAULT 0,
  `stage_id` varchar(16) DEFAULT NULL,
  `stage_name` varchar(36) DEFAULT NULL,
  `stage_order` varchar(3) DEFAULT NULL,
  `ope_no` varchar(16) DEFAULT NULL,
  `ope_name` varchar(36) DEFAULT NULL,
  `powder_type` varchar(24) DEFAULT NULL,
  `powder_id` varchar(24) DEFAULT NULL,
  `cust_id` varchar(16) DEFAULT NULL,
  `cust_name` varchar(36) DEFAULT NULL,
  `tool_id_erp` varchar(12) DEFAULT NULL COMMENT 'erp tool id for link customer''s erp system - 2020/02/06 lkche a',
  `tool_id_code1` varchar(12) DEFAULT NULL COMMENT 'for lase marking naming rue -- 2020/02/11 lkchena',
  `lp_cnt` int(11) DEFAULT NULL COMMENT 'load port 數量',
  `ch_cnt` int(11) DEFAULT NULL COMMENT 'chamber 數量',
  `area_id` varchar(12) DEFAULT NULL,
  `area_name` varchar(24) DEFAULT NULL COMMENT '2020/04/14 lkchena',
  `pos_id` varchar(12) DEFAULT NULL,
  `dept` varchar(12) DEFAULT NULL,
  `sponsor` varchar(16) DEFAULT NULL,
  `phone` varchar(16) DEFAULT NULL,
  `move_peak` int(11) DEFAULT NULL COMMENT 'peak of daily move\n\n2020/03/13 lkchena:\nuse tool_grp_id_r: tgir to dynamic get different move_peak in the furture oee code',
  `move_mean` int(11) DEFAULT NULL COMMENT 'daily move(capability)\n\n2020/03/13 lkchena:\nuse tool_grp_id_r: tgir to dynamic get different move_peak in the furture oee code',
  `tgir` varchar(24) DEFAULT NULL COMMENT '2020/03/13 lkchena\n\ntool_grp_id --> default tool group\ntg: tool_grp\ntgir: tool_grp_id_run  current run tool_grp_id\ntgi: tool_grp_id_1~10:  tool option group 1~10\n',
  `tgi1` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi2` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi3` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi4` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi5` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi6` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi7` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi8` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi9` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgi10` varchar(24) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tgr` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg1` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg2` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg3` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg4` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg5` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg6` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg7` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg8` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg9` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `tg10` varchar(32) DEFAULT NULL COMMENT 'see tigr definition -- 2020/03/13 lkchena',
  `rec_user` varchar(16) DEFAULT NULL,
  `rec_time` varchar(19) DEFAULT NULL,
  `enable_tcs` varchar(1) DEFAULT 'N' COMMENT 'Y/N 2018/05/23 lkchena: we can''t download command to tool currently, so we set the flag to judge',
  `ip_addr` varchar(16) DEFAULT NULL COMMENT 'keep the field for future control 2018/05/23 lkchena',
  `dcop_type` int(11) DEFAULT 0 COMMENT '0: no dcop \n1: raw( 1 sec )\n2:compact( with purge )\n\n2019/11/29 lkchena',
  `function` varchar(24) DEFAULT NULL COMMENT 'for old dcop,when new dcop release, we can drop it\n-- 2019/12/17 lkchena',
  `flag00` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: ',
  `flag01` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: need pre-job, ex: forming tool 2020/04/21 lkchena',
  `flag02` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: need test before product, ex: forming tool 2020/04/21 lkchena',
  `flag03` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: ',
  `flag04` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: ',
  `flag05` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: first stb tool, ex: forming tool 2020/04/21 lkchena',
  `flag06` int(11) NOT NULL DEFAULT 0 COMMENT 'flag: trackin cart_no before wip run(cart_no is null)(forming/sinter-backend), others is directly trackin cart_no(wip has cart_no)',
